/// Returns the Stage 0 half-band unique positive odd taps for a given preset.
pub fn get_halfband_stage0_taps(preset: FilterPreset) -> &'static [f64] {
    match preset {
        FilterPreset::Balanced => &HALFBAND_STAGE0_BALANCED_ODD_TAPS,
        FilterPreset::Reference => &HALFBAND_STAGE0_REFERENCE_ODD_TAPS,
        FilterPreset::LowLatency => &HALFBAND_STAGE0_LOW_LATENCY_ODD_TAPS,
    }
}

/// Returns the Stage 1+ half-band unique positive odd taps for a given preset.
pub fn get_halfband_stage1_taps(preset: FilterPreset) -> &'static [f64] {
    match preset {
        FilterPreset::Balanced => &HALFBAND_STAGE1_BALANCED_ODD_TAPS,
        FilterPreset::Reference => &HALFBAND_STAGE1_REFERENCE_ODD_TAPS,
        FilterPreset::LowLatency => &HALFBAND_STAGE1_LOW_LATENCY_ODD_TAPS,
    }
}

/// Stage filter coefficients selected by phase and apodization mode.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum HalfBandTaps {
    /// Symmetric half-band prototype stored as unique positive odd taps.
    Symmetric(&'static [f64]),
    /// General full-length FIR prototype stored as all taps.
    General(&'static [f64]),
}

/// Returns the Stage 0 filter taps for a preset, phase, and apodization combination.
pub fn get_halfband_stage0_filter(
    preset: FilterPreset,
    phase: FilterPhase,
    apodization: Apodization,
) -> HalfBandTaps {
    match (phase, apodization) {
        (FilterPhase::Linear, Apodization::Off) => {
            HalfBandTaps::Symmetric(get_halfband_stage0_taps(preset))
        }
        (FilterPhase::Linear, Apodization::Gentle) => HalfBandTaps::General(match preset {
            FilterPreset::Balanced => &HALFBAND_STAGE0_BALANCED_LINEAR_GENTLE_TAPS,
            FilterPreset::Reference => &HALFBAND_STAGE0_REFERENCE_LINEAR_GENTLE_TAPS,
            FilterPreset::LowLatency => &HALFBAND_STAGE0_LOW_LATENCY_LINEAR_GENTLE_TAPS,
        }),
        (FilterPhase::Minimum, Apodization::Off) => HalfBandTaps::General(match preset {
            FilterPreset::Balanced => &HALFBAND_STAGE0_BALANCED_MINIMUM_OFF_TAPS,
            FilterPreset::Reference => &HALFBAND_STAGE0_REFERENCE_MINIMUM_OFF_TAPS,
            FilterPreset::LowLatency => &HALFBAND_STAGE0_LOW_LATENCY_MINIMUM_OFF_TAPS,
        }),
        (FilterPhase::Minimum, Apodization::Gentle) => HalfBandTaps::General(match preset {
            FilterPreset::Balanced => &HALFBAND_STAGE0_BALANCED_MINIMUM_GENTLE_TAPS,
            FilterPreset::Reference => &HALFBAND_STAGE0_REFERENCE_MINIMUM_GENTLE_TAPS,
            FilterPreset::LowLatency => &HALFBAND_STAGE0_LOW_LATENCY_MINIMUM_GENTLE_TAPS,
        }),
    }
}

/// Returns the Stage 1+ filter taps for a preset and phase. Apodization only affects Stage 0.
pub fn get_halfband_stage1_filter(preset: FilterPreset, phase: FilterPhase) -> HalfBandTaps {
    match phase {
        FilterPhase::Linear => HalfBandTaps::Symmetric(get_halfband_stage1_taps(preset)),
        FilterPhase::Minimum => HalfBandTaps::General(match preset {
            FilterPreset::Balanced => &HALFBAND_STAGE1_BALANCED_MINIMUM_OFF_TAPS,
            FilterPreset::Reference => &HALFBAND_STAGE1_REFERENCE_MINIMUM_OFF_TAPS,
            FilterPreset::LowLatency => &HALFBAND_STAGE1_LOW_LATENCY_MINIMUM_OFF_TAPS,
        }),
    }
}

/// SRC prototype cutoff, as a fraction of the lower of the two rates (Design.md §4.2, `design_src.py`).
pub const SRC_CUTOFF: f64 = 0.5;
/// SRC passband edge (20 kHz at 44.1 kHz), as a fraction of the lower rate.
pub const SRC_PASS_EDGE: f64 = 0.45351473922902497;
/// SRC stopband edge (24.1 kHz at 44.1 kHz), as a fraction of the lower rate.
pub const SRC_STOP_EDGE: f64 = 0.546485260770975;
/// Kaiser window beta of the SRC prototype (140 dB design attenuation).
pub const SRC_KAISER_BETA: f64 = 14.469260000000002;
/// SRC taps per output sample when no downsampling is involved (measured prototype: passband deviation 7.7e-07 dB, rejection 141.0 dB).
pub const SRC_TAPS_UNITY: usize = 110;
/// Phases of the ASRC bank; positions between phases are cubic (4-point Lagrange) interpolated.
pub const SRC_ASRC_PHASES: usize = 256;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_crfb_coefficient_lookups() {
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD64).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD128).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD256).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD512).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD64_48).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD128_48).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD256_48).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD512_48).is_some());

        let dsd256 = get_crfb_coefficients(DsdBitRateHz::DSD256).unwrap();
        assert!(dsd256.g1 > 0.0);
        assert!(dsd256.g2 > 0.0);
        assert!(dsd256.b1 > 0.0);
        assert_eq!(dsd256.a.len(), 5);
        for &a_val in &dsd256.a {
            assert!(a_val > 0.0);
        }

        let dsd512 = get_crfb_coefficients(DsdBitRateHz::DSD512).unwrap();
        assert!(dsd512.g1 > 0.0);
        assert!(dsd512.g2 > 0.0);
        assert!(dsd512.b1 > 0.0);
        assert_eq!(dsd512.a.len(), 5);
        for &a_val in &dsd512.a {
            assert!(a_val > 0.0);
        }

        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD64).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD128).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD256).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD512).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD64_48).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD128_48).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD256_48).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD512_48).is_some());

        let dsd256_7 = get_crfb7_coefficients(DsdBitRateHz::DSD256).unwrap();
        assert!(dsd256_7.g1 > 0.0);
        assert!(dsd256_7.g2 > 0.0);
        assert!(dsd256_7.g3 > 0.0);
        assert!(dsd256_7.b1 > 0.0);
        assert_eq!(dsd256_7.a.len(), 7);
        for &a_val in &dsd256_7.a {
            assert!(a_val > 0.0);
        }

        let dsd512_7 = get_crfb7_coefficients(DsdBitRateHz::DSD512).unwrap();
        assert!(dsd512_7.g1 > 0.0);
        assert!(dsd512_7.g2 > 0.0);
        assert!(dsd512_7.g3 > 0.0);
        assert!(dsd512_7.b1 > 0.0);
        assert_eq!(dsd512_7.a.len(), 7);
        for &a_val in &dsd512_7.a {
            assert!(a_val > 0.0);
        }
    }

    #[test]
    fn test_halfband_taps_lookup_and_symmetry() {
        let s0_bal = get_halfband_stage0_taps(FilterPreset::Balanced);
        assert_eq!(s0_bal.len(), 44);
        let s0_ref = get_halfband_stage0_taps(FilterPreset::Reference);
        assert_eq!(s0_ref.len(), 50);
        let s0_ll = get_halfband_stage0_taps(FilterPreset::LowLatency);
        assert_eq!(s0_ll.len(), 35);

        let s1_bal = get_halfband_stage1_taps(FilterPreset::Balanced);
        assert_eq!(s1_bal.len(), 7);
        let s1_ref = get_halfband_stage1_taps(FilterPreset::Reference);
        assert_eq!(s1_ref.len(), 8);
        let s1_ll = get_halfband_stage1_taps(FilterPreset::LowLatency);
        assert_eq!(s1_ll.len(), 6);

        let odd_sum_s1_bal: f64 = s1_bal.iter().sum::<f64>() * 2.0;
        assert!((odd_sum_s1_bal - 0.5).abs() < 1e-6);

        let odd_sum_s0_ref: f64 = s0_ref.iter().sum::<f64>() * 2.0;
        assert!((odd_sum_s0_ref - 0.5).abs() < 1e-6);
    }

    fn general_taps(taps: HalfBandTaps) -> &'static [f64] {
        match taps {
            HalfBandTaps::General(taps) => taps,
            HalfBandTaps::Symmetric(_) => panic!("expected general full-length taps"),
        }
    }

    #[test]
    fn test_halfband_phase_apodization_matrix() {
        use Apodization::{Gentle, Off};
        use FilterPhase::{Linear, Minimum};

        // (Linear, Off) keeps using the symmetric half-band odd taps.
        for preset in [
            FilterPreset::Balanced,
            FilterPreset::Reference,
            FilterPreset::LowLatency,
        ] {
            assert!(matches!(
                get_halfband_stage0_filter(preset, Linear, Off),
                HalfBandTaps::Symmetric(_)
            ));
        }

        let expected_stage0 = [
            (FilterPreset::Balanced, 159usize, 175usize, 159usize),
            (FilterPreset::Reference, 185usize, 199usize, 185usize),
            (FilterPreset::LowLatency, 131usize, 139usize, 131usize),
        ];
        for (preset, gentle_len, minimum_len, minimum_gentle_len) in expected_stage0 {
            let gentle = general_taps(get_halfband_stage0_filter(preset, Linear, Gentle));
            assert_eq!(gentle.len(), gentle_len);
            assert!((gentle.iter().sum::<f64>() - 1.0).abs() < 1e-6);

            let minimum = general_taps(get_halfband_stage0_filter(preset, Minimum, Off));
            assert_eq!(minimum.len(), minimum_len);
            assert!((minimum.iter().sum::<f64>() - 1.0).abs() < 1e-6);

            let minimum_gentle = general_taps(get_halfband_stage0_filter(preset, Minimum, Gentle));
            assert_eq!(minimum_gentle.len(), minimum_gentle_len);
            assert!((minimum_gentle.iter().sum::<f64>() - 1.0).abs() < 1e-6);
        }

        let expected_stage1 = [
            (FilterPreset::Balanced, 27usize),
            (FilterPreset::Reference, 31usize),
            (FilterPreset::LowLatency, 23usize),
        ];
        for (preset, minimum_len) in expected_stage1 {
            assert!(matches!(
                get_halfband_stage1_filter(preset, Linear),
                HalfBandTaps::Symmetric(_)
            ));
            let minimum = general_taps(get_halfband_stage1_filter(preset, Minimum));
            assert_eq!(minimum.len(), minimum_len);
            assert!((minimum.iter().sum::<f64>() - 1.0).abs() < 1e-6);
        }
    }
}
